fun transition(next: OrderStatus): String {
        if (status != OrderStatus.QUEUED) return "unchanged"
        val message = when (next) {
            OrderStatus.BREWED -> "collected"
            OrderStatus.CANCELLED -> "refunded"
            else -> "unchanged"
        }
        status = next
        return message
    }

